(32) USEPARAMETERACCESS = FALSE;
(33) USERESSCHEDULER = TRUE;
(34) 
(35) KERNEL_TYPE = ECC2;
        </pre>
The following configuration code, from line 1 to line 65, defines the application tasks. Note that, each task defines its private stack, all tasks are activated at the system start up (AUTOSTART = TRUE), namely after that the <code>StartOS()</code> function is called, which in turn is called by <code>QF_run()</code>, see the file <code>qf_port.c</code>. The code at line 67 defines the '''Event''' variable <code>QFEvent</code>, which is used for the blocking mechanism of '''QP''' event queues. The code from line <math>70</math> to line <math>74</math> enables the system tick interrupt and defines the related ISR.

<pre>    
(1) TASK Philo0Task {
(2)     PRIORITY = 0x01;
(3)     AUTOSTART = TRUE; { /* NOTE: AUTOSTART should be always TRUE*/}
(4)    STACK = PRIVATE {
(5)     SYS_SIZE = 512;
(6)     };
(7)     ACTIVATION = 1;    /* only one pending activation */
(8)     SCHEDULE = FULL;
(9)     EVENT = QFEvent;
(10) };
(11)
(12) TASK Philo1Task {
(13)     PRIORITY = 0x02;
(14)     AUTOSTART = TRUE;  /* NOTE: AUTOSTART should be always TRUE*/
(15)     STACK = PRIVATE {
(16)         SYS_SIZE = 512;
(17)     };
(18)     ACTIVATION = 1;    /* only one pending activation */
(19)     SCHEDULE = FULL;
(20)     EVENT = QFEvent;
(21) };
(22)     
(23) TASK Philo2Task {
(24)     PRIORITY = 0x03;
(25)     AUTOSTART = TRUE;  /* NOTE: AUTOSTART should be always TRUE*/
(26)     STACK = PRIVATE {
(27)         SYS_SIZE = 512;
(28)     };
(29)     ACTIVATION = 1;    /* only one pending activation */
(30)     SCHEDULE = FULL;
(31)     EVENT = QFEvent;
(32) };
(33) 
(34) TASK Philo3Task {
(35)    PRIORITY = 0x04;
(36)     AUTOSTART = TRUE;  /* NOTE: AUTOSTART should be always TRUE*/
(37)     STACK = PRIVATE {
(38)         SYS_SIZE = 512;
(39)     };
(40)     ACTIVATION = 1;    /* only one pending activation */
(41)     SCHEDULE = FULL;
(42)     EVENT = QFEvent;
(43) };
(44)     
(45) TASK Philo4Task {
(46)     PRIORITY = 0x05;
(47)     AUTOSTART = TRUE;  /* NOTE: AUTOSTART should be always TRUE*/
(48)     STACK = PRIVATE {
(49)         SYS_SIZE = 512;
(50)     };
(51)     ACTIVATION = 1;    /* only one pending activation */
(52)     SCHEDULE = FULL;
(53)     EVENT = QFEvent;
(54) };
(55)     
(56) TASK TableTask {
(57)     PRIORITY = 0x06;
(58)     AUTOSTART = TRUE;  /* NOTE: AUTOSTART should be always TRUE*/
(59)     STACK = PRIVATE {
(60)         SYS_SIZE = 512;
(61)     };
(62)     ACTIVATION = 1;    /* only one pending activation */
(63)     SCHEDULE = FULL;
(64)     EVENT = QFEvent;
(65) };
(66)     
