(9)     STM32F4XX_SPD = ENABLE {
(10)        USEGPIO = TRUE;
(11)         USEEXTI = TRUE;
(12)         USESYSCFG = TRUE; 
(13)         USEMISC = TRUE;
(14)         };
(15)     };
(16)         
