(9)     STM32F4XX_SPD = ENABLE {
(10)        USEGPIO = TRUE;
(11)         USEEXTI = TRUE;
(12)         USESYSCFG = TRUE; 
(13)         USEMISC = TRUE;
(14)         };
(15)     };
(16)         
(17) LIB = ENABLE { NAME = &quot;STM32F4_DISCOVERY&quot;;
(18)     STM32F4_DISCOVERY = ENABLE {
(19)     USELEDS = TRUE;
(20)     USEBUTTONS = TRUE;
(21)     };
(22) };
(23)         
(24)         
