(24)     PRIORITY = 0x03;
(25)     AUTOSTART = TRUE;  /* NOTE: AUTOSTART should be always TRUE*/
(26)     STACK = PRIVATE {
(27)         SYS_SIZE = 512;
(28)     };
(29)     ACTIVATION = 1;    /* only one pending activation */
(30)     SCHEDULE = FULL;
(31)     EVENT = QFEvent;
(32) };
(33) 
(34) TASK Philo3Task {
(35)    PRIORITY = 0x04;
(36)     AUTOSTART = TRUE;  /* NOTE: AUTOSTART should be always TRUE*/
(37)     STACK = PRIVATE {
(38)         SYS_SIZE = 512;
(39)     };
(40)     ACTIVATION = 1;    /* only one pending activation */
(41)     SCHEDULE = FULL;
(42)     EVENT = QFEvent;
(43) };
(44)     
(45) TASK Philo4Task {
(46)     PRIORITY = 0x05;
(47)     AUTOSTART = TRUE;  /* NOTE: AUTOSTART should be always TRUE*/
(48)     STACK = PRIVATE {
(49)         SYS_SIZE = 512;
(50)     };
(51)     ACTIVATION = 1;    /* only one pending activation */
(52)     SCHEDULE = FULL;
(53)     EVENT = QFEvent;
(54) };
(55)     
(56) TASK TableTask {
(57)     PRIORITY = 0x06;
(58)     AUTOSTART = TRUE;  /* NOTE: AUTOSTART should be always TRUE*/
(59)     STACK = PRIVATE {
(60)         SYS_SIZE = 512;
(61)     };
(62)     ACTIVATION = 1;    /* only one pending activation */
(63)     SCHEDULE = FULL;
(64)     EVENT = QFEvent;
